mapper.select:
SELECT o.orders_id, o.state, o.update_time, o.order_taking_id, u.user_id, u.user_name, u.avatar, (select count(*) from taking_commnt c where c.orders_id=o.orders_id and c.user_id=#{userId}) as commentCount, g.game_name, g.game_img, o.order_number, o.pay_money, t.classify, t.unit, o.rate, o.zhi_rate as zhiRate, o.zhi_user_id as zhiUserId, o.fei_user_id as feiUserId, o.fei_rate as feiRate, o.ping_rate as pingRate, o.coupon_id as couponId, o.order_type as orderType, o.coupon_money as couponMoney, o.consortia_rate as consortiaRate, o.consortia_user_id as consortiaUserId, t.id as orderTakingId FROM orders o LEFT JOIN order_taking t ON o.order_taking_id = t.id LEFT JOIN game g ON t.game_id = g.id LEFT JOIN tb_user u ON u.user_id = t.user_id WHERE o.orders_type = 1 and o.isdelete=0 and o.orders_id is not null AND o.user_id = #{userId}
and o.state=#{status}
order by o.create_time desc

SELECT o.orders_id, o.orders_no, o.order_taking_id, o.pay_money, o.state, o.create_time, o.orders_type, o.remarks, o.order_number, o.vip_details_id, u.user_name, u.avatar, ou.user_name as ordersUserName, ou.avatar as ordersUserAvatar, o.user_id as ordersUserId, o.order_score, t.user_id, t.old_money as oldMoney, t.money, t.classify, t.unit, o.rate, o.zhi_rate as zhiRate, o.zhi_user_id as zhiUserId, o.fei_user_id as feiUserId, o.fei_rate as feiRate, o.order_type as orderType, o.ping_rate as pingRate, o.coupon_id as couponId, o.coupon_money as couponMoney, o.consortia_rate as consortiaRate, o.consortia_user_id as consortiaUserId, (select user_name from tb_user u2 where u2.user_id=o.zhi_user_id) as zhiUserName, (select user_name from tb_user u2 where u2.user_id=o.fei_user_id) as feiUserName, t.member_money as memberMoney FROM orders o LEFT JOIN order_taking t ON o.order_taking_id = t.id LEFT JOIN game g ON t.game_id = g.id LEFT JOIN tb_user u ON u.user_id = t.user_id left join tb_user ou on ou.user_id = o.user_id WHERE o.isdelete=0
and o.orders_type=#{type}
and o.state=#{status}
and ou.user_name like #{orderName}
and u.user_name like #{name}
and o.orders_no = #{ordersNo}
and o.user_id=#{userId}
and o.order_type=#{orderType}
and o.orders_type=#{ordersType}
and date_format(o.create_time,'%Y-%m-%d')>=date_format(#{startTime},'%Y-%m-%d')
and date_format(o.create_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')
order by o.create_time desc

SELECT o.orders_id, o.orders_no, o.order_taking_id, o.pay_money, o.state, o.create_time, o.orders_type, o.remarks, o.order_number, o.vip_details_id, u.user_name, u.avatar, ou.user_name as ordersUserName, ou.avatar as ordersUserAvatar, o.user_id as ordersUserId, o.order_score, t.user_id, t.old_money as oldMoney, t.money, t.classify, t.unit, o.rate, o.zhi_rate as zhiRate, o.zhi_user_id as zhiUserId, o.fei_user_id as feiUserId, o.fei_rate as feiRate, o.orders_type as ordersType, o.order_type as orderType, o.ping_rate as pingRate, o.coupon_id as couponId, o.coupon_money as couponMoney, o.consortia_rate as consortiaRate, o.consortia_user_id as consortiaUserId, (select user_name from tb_user u2 where u2.user_id=o.zhi_user_id) as zhiUserName, (select user_name from tb_user u2 where u2.user_id=o.fei_user_id) as feiUserName, t.member_money as memberMoney FROM orders o LEFT JOIN order_taking t ON o.order_taking_id = t.id LEFT JOIN game g ON t.game_id = g.id LEFT JOIN tb_user u ON u.user_id = t.user_id left join tb_user ou on ou.user_id = o.user_id WHERE o.isdelete=0
and o.orders_type=#{type}
and o.state=#{status}
and ou.user_name like #{orderName}
and u.user_name like #{name}
and o.orders_no = #{ordersNo}
and o.user_id=#{userId}
and o.order_type=#{orderType}
and o.orders_type=#{ordersType}
and date_format(o.create_time,'%Y-%m-%d')>=date_format(#{startTime},'%Y-%m-%d')
and date_format(o.create_time,'%Y-%m-%d')<=date_format(#{endTime},'%Y-%m-%d')
order by o.create_time desc

select o.orders_id as ordersId,o.state,o.create_time as createTime,o.pay_money as payMoney,o.user_id as ordersUserId,ot.classify,ot.unit, u.user_name as userName,u.avatar,o.order_number as orderNumber,o.remarks,o.orders_no as ordersNo,ot.old_money as oldMoney, g.game_name as gameName,g.game_img as gameImg,ot.id as orderTakingId, o.rate, o.zhi_rate as zhiRate, o.order_type as orderType, o.zhi_user_id as zhiUserId, o.fei_user_id as feiUserId, o.fei_rate as feiRate, o.coupon_id as couponId, o.coupon_money as couponMoney, o.ping_rate as pingRate from orders o left join order_taking ot on ot.id=o.order_taking_id left join game g on g.id=ot.game_id left join tb_user u on u.user_id=o.user_id where ot.user_id=#{userId} and o.orders_type=1
and o.state=#{status}
order by o.create_time desc

select o.orders_id as ordersId,o.state,o.create_time as createTime,o.pay_money as payMoney,o.user_id as ordersUserId,ot.classify,ot.unit, u.user_name as userName,u.avatar,o.order_number as orderNumber,o.remarks,o.orders_no as ordersNo,ot.old_money as oldMoney, o.coupon_id as couponId, o.order_type as orderType, o.coupon_money as couponMoney, g.game_name as gameName,g.game_img as gameImg,ot.id as orderTakingId,o.zhi_rate as zhiRate,o.fei_rate as feiRate from orders o left join order_taking ot on ot.id=o.order_taking_id left join game g on g.id=ot.game_id left join tb_user u on u.user_id=o.user_id where o.orders_type=1
and o.state=#{status}
and o.zhi_user_id=#{userId}
and o.fei_user_id=#{userId}
order by o.create_time desc

select
ifnull(sum(zhi_rate),0.00)
ifnull(sum(fei_rate),0.00)
from orders where state=2
and zhi_user_id=#{userId}
and fei_user_id=#{userId}

select count(*) from tb_user where
inviter_code=#{invitationCode}
inviter_code in (select invitation_code from tb_user where inviter_code=#{invitationCode})

select count(*) from orders where orders_type=1
and order_type=#{orderType}
and `state`=#{state}
and date_format(create_time,'%Y-%m-%d')=date_format(#{time},'%Y-%m-%d')
and date_format(create_time,'%Y-%m')=date_format(#{time},'%Y-%m')
and date_format(create_time,'%Y')=date_format(#{time},'%Y')
